function tripDistance(mainTank: number, reserveTank: number): number {
  let distance = 0;
  while (mainTank >= 5) {
    mainTank -= 5;
    distance += 50;
    if (reserveTank > 0) { reserveTank--; mainTank++; }
  }
  return distance + mainTank * 10;
}

