class Solution:
    def tripDistance(self, mainTank: int, reserveTank: int) -> int:
        distance = 0
        while mainTank >= 5:
            mainTank -= 5
            distance += 50
            if reserveTank:
                reserveTank -= 1
                mainTank += 1
        return distance + mainTank * 10

